    if(p.storageMode==='table'){p.table=pairs();p.floor=p.table[0][0];if(p.h0<p.table[0][0]||p.h0>p.table.at(-1)[0]||p.href<p.table[0][0]||p.href>p.table.at(-1)[0])throw new Error('Initial water level and reference level Href must lie within the declared stage-storage table range.');}
